mapper.select:
SELECT *
FROM lunaerp_stock_in_item
WHERE stock_in_id = #{stockInId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
ORDER BY id ASC

mapper.update:
UPDATE lunaerp_stock_in_item
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE stock_in_id = #{stockInId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_stock_in_item
WHERE stock_in_id = #{stockInId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
